-- Vale of Eternal Blossoms: creature abilities
-- No reference scripts the zone's creatures (the mogu, the Sha, the mantid and the Shao-Tien), and most had no AI: they cast their
-- sniffed spells (creature_template spell1-8).

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '59146,59157,59158,59973,60373,61968,63082,63219,63605,63939,63948,63950,64200,64201,64586,65130,65131,65134,65136,65140,65824,65978';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
